import{_ as t,c as a,o as r,ag as o}from"./chunks/framework.DgwiViYK.js";const m=JSON.parse('{"title":"Développement mobile – Flutter & React Native","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1760301764000}'),i={name:"index.md"};function n(s,e,l,c,p,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="developpement-mobile-–-flutter-react-native" tabindex="-1">Développement mobile – Flutter &amp; React Native <a class="header-anchor" href="#developpement-mobile-–-flutter-react-native" aria-label="Permalink to &quot;Développement mobile – Flutter &amp; React Native&quot;">​</a></h1><p>Bienvenue dans le syllabus complet de développement mobile cross-platform. Ce cours vous accompagnera dans l&#39;apprentissage de deux technologies majeures du développement mobile moderne : <strong>Flutter</strong> avec le langage <strong>Dart</strong>, et <strong>React Native</strong>.</p><h2 id="🎯-objectifs-d-apprentissage" tabindex="-1">🎯 Objectifs d&#39;apprentissage <a class="header-anchor" href="#🎯-objectifs-d-apprentissage" aria-label="Permalink to &quot;🎯 Objectifs d&#39;apprentissage&quot;">​</a></h2><p>À la fin de ce parcours, vous serez capable de :</p><ul><li>Maîtriser les fondamentaux du langage <strong>Dart</strong> et ses spécificités</li><li>Développer des applications mobiles avec <strong>Flutter</strong> en utilisant l&#39;architecture <strong>BLoC</strong></li><li>Intégrer vos applications Flutter avec <strong>Firebase</strong> et <strong>Cloud Firestore</strong></li><li>Créer des applications <strong>React Native</strong> en exploitant vos connaissances React</li><li>Comprendre les différences entre développement natif, hybride et cross-platform</li><li>Choisir la technologie appropriée selon le contexte du projet</li></ul><h2 id="📱-technologies-couvertes" tabindex="-1">📱 Technologies couvertes <a class="header-anchor" href="#📱-technologies-couvertes" aria-label="Permalink to &quot;📱 Technologies couvertes&quot;">​</a></h2><h3 id="flutter-dart" tabindex="-1">Flutter &amp; Dart <a class="header-anchor" href="#flutter-dart" aria-label="Permalink to &quot;Flutter &amp; Dart&quot;">​</a></h3><ul><li>Langage Dart : syntaxe, programmation asynchrone, null safety</li><li>Framework Flutter : widgets, gestion d&#39;état, architecture</li><li>Pattern BLoC pour une architecture maintenable</li><li>Intégration Firebase pour l&#39;authentification et les données</li></ul><h3 id="react-native" tabindex="-1">React Native <a class="header-anchor" href="#react-native" aria-label="Permalink to &quot;React Native&quot;">​</a></h3><ul><li>Composants natifs et mise en page</li><li>Navigation entre écrans</li><li>Accès aux APIs natives du mobile</li><li>Bonnes pratiques cross-platform</li></ul><h2 id="🗂️-structure-du-cours" tabindex="-1">🗂️ Structure du cours <a class="header-anchor" href="#🗂️-structure-du-cours" aria-label="Permalink to &quot;🗂️ Structure du cours&quot;">​</a></h2><p>Le syllabus est organisé en quatre sections principales :</p><ol><li><strong><a href="./introduction.html">Introduction au développement mobile</a></strong> - Vue d&#39;ensemble et environnements de développement</li><li><strong><a href="./dart/">Langage Dart</a></strong> - Fondamentaux et syntaxe avancée</li><li><strong><a href="./flutter/">Flutter Framework</a></strong> - De l&#39;interface utilisateur à l&#39;architecture complète</li><li><strong><a href="./react-native/">React Native</a></strong> - Développement cross-platform avec JavaScript</li></ol><h2 id="💡-prerequis" tabindex="-1">💡 Prérequis <a class="header-anchor" href="#💡-prerequis" aria-label="Permalink to &quot;💡 Prérequis&quot;">​</a></h2><p>Ce cours s&#39;adresse à des étudiants ayant déjà une expérience en programmation :</p><ul><li>Maîtrise de la programmation orientée objet (Java, C#)</li><li>Connaissances de base en JavaScript</li><li>Familiarité avec les concepts de développement web (optionnel mais recommandé)</li></ul><div class="tip custom-block"><p class="custom-block-title">Conseil pédagogique</p><p>Chaque section contient des exemples pratiques et des exercices progressifs. N&#39;hésitez pas à expérimenter avec le code proposé pour bien assimiler les concepts.</p></div><h2 id="🚀-pour-commencer" tabindex="-1">🚀 Pour commencer <a class="header-anchor" href="#🚀-pour-commencer" aria-label="Permalink to &quot;🚀 Pour commencer&quot;">​</a></h2><p>Commencez par la section <a href="./introduction.html">Introduction au développement mobile</a> pour découvrir l&#39;écosystème du développement mobile et configurer votre environnement de développement.</p><p>Bonne découverte du développement mobile !</p>',20)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
